-- Harméa MVP: PostgreSQL/PGlite-compatible starter schema.
-- Initial schema only. UUIDs/tokens are generated by the application.
-- Business state transitions and snapshot immutability are enforced in Service code.

CREATE TABLE products (
  id uuid PRIMARY KEY,
  name varchar(120) NOT NULL,
  unit_price_vnd integer NOT NULL CHECK (unit_price_vnd >= 0),
  template_version varchar(40) NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  is_demo boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
-- This MVP deliberately has at most one currently sold product.
CREATE UNIQUE INDEX one_active_product ON products ((is_active)) WHERE is_active;

CREATE TABLE orders (
  id uuid PRIMARY KEY,
  order_number varchar(24) NOT NULL UNIQUE,
  request_key uuid NOT NULL UNIQUE,
  product_id uuid NOT NULL REFERENCES products(id),
  product_snapshot jsonb NOT NULL CHECK (jsonb_typeof(product_snapshot) = 'object'),
  design_snapshot jsonb NOT NULL CHECK (jsonb_typeof(design_snapshot) = 'object'),
  recipient_snapshot jsonb NOT NULL CHECK (jsonb_typeof(recipient_snapshot) = 'object'),
  quantity integer NOT NULL CHECK (quantity BETWEEN 1 AND 10),
  unit_price_vnd integer NOT NULL CHECK (unit_price_vnd >= 0),
  subtotal_vnd integer NOT NULL CHECK (subtotal_vnd = unit_price_vnd * quantity),
  currency varchar(3) NOT NULL DEFAULT 'VND' CHECK (currency = 'VND'),
  customer_note varchar(500) NOT NULL DEFAULT '',
  photo_key varchar(255) NOT NULL CHECK (photo_key <> ''),
  preview_key varchar(255) NOT NULL CHECK (preview_key <> ''),
  tracking_token_hash varchar(64) NOT NULL UNIQUE CHECK (tracking_token_hash ~ '^[0-9a-f]{64}$'),
  status varchar(16) NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','confirmed','producing','shipping','completed','cancelled')),
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  tracking_code varchar(80),
  cancellation_reason varchar(500),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (status <> 'cancelled' OR (cancellation_reason IS NOT NULL AND length(trim(cancellation_reason)) > 0))
);
CREATE INDEX orders_created_at_idx ON orders (created_at DESC, id);
CREATE INDEX orders_status_created_at_idx ON orders (status, created_at DESC);

CREATE TABLE order_status_events (
  id uuid PRIMARY KEY,
  order_id uuid NOT NULL REFERENCES orders(id),
  order_version integer NOT NULL CHECK (order_version > 0),
  from_status varchar(16)
    CHECK (from_status IN ('pending','confirmed','producing','shipping','completed','cancelled')),
  to_status varchar(16) NOT NULL
    CHECK (to_status IN ('pending','confirmed','producing','shipping','completed','cancelled')),
  actor varchar(10) NOT NULL CHECK (actor IN ('guest','admin','system')),
  internal_note varchar(500),
  occurred_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (order_id, order_version)
);
CREATE INDEX order_status_events_order_idx ON order_status_events (order_id, occurred_at, id);

CREATE TABLE admin_sessions (
  id uuid PRIMARY KEY,
  token_hash varchar(64) NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at timestamptz NOT NULL,
  CHECK (expires_at > created_at)
);
CREATE INDEX admin_sessions_expiry_idx ON admin_sessions (expires_at);

COMMENT ON TABLE orders IS 'One design per order. No payment/cart/account/order_items in the MVP.';
COMMENT ON COLUMN orders.subtotal_vnd IS 'Merchandise only; shipping is not quoted and API shippingFeeVnd is null.';
COMMENT ON COLUMN orders.design_snapshot IS 'Immutable submitted fields/crop/template reference; preview is a visual proof, not a guaranteed production print file.';
COMMENT ON COLUMN orders.photo_key IS 'Application-generated relative storage key, never a user-supplied path or public URL.';
COMMENT ON COLUMN orders.tracking_token_hash IS 'SHA-256 hash only. Raw secret returned once on successful create.';

